<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to rewrite:
<original_code>
//#pragma comment(linker, "/STACK:1024000000,1024000000")
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <cassert>
#include <map>
#include <set>
#include <queue>
#include <stack>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#define  RD(x)      scanf("%d", &x)
#define  REP(i, n)  for (int i=0; i<int(n); i++)
#define  FOR(i, n)  for (int i=1; i<=int(n); i++)
#define  pii        pair<int, int>
#define  piL        pair<int, long long>
#define  mp         make_pair
#define  pb         push_back
inline   int read(){int ret; scanf("%d", &ret); return ret;}
int dx8[8] = {1, 1, 0, -1, -1, -1, 0, 1};
int dy8[8] = {0, 1, 1, 1, 0, -1, -1, -1};
int dx4[4] = {1, 0, -1, 0};
int dy4[4] = {0, 1, 0, -1};

using namespace std;
#define  N   33
#define  eps 1e-8
#define  pi  acos(-1.0)
#define  inf 0XFFFFFFFll
#define  mod 1000000007ll
#define  LL  long long
#define  ULL unsigned long long

inline void add(LL &x, LL y) {
	x = (x + y) % mod;
}

int r;

struct Matrix {
	LL a[N][N];
	void toZero() {
		memset(a, 0, sizeof a);
	}
	void toE() {
		toZero();
		REP(i, r)
			a[i][i] = 1;
	}
	friend Matrix operator * (const Matrix &a, const Matrix &b) {
		Matrix ret; ret.toZero();
		REP(i, r) REP(j, r) REP(k, r)
				add(ret.a[i][j], a.a[i][k] * b.a[k][j]);
		return ret;
	}
};

LL n, K;
Matrix one[70];
Matrix two[70];
Matrix rotr[70], rotc[70];

int Main() {
    ios_base::sync_with_stdio(0);

    cin >> n >> K;
    r = K + 1;

    // 0 - > single 1
    // i - > i - 1
    REP(i, K+1) {
    	one[i].toE();
    	if (i)
    		REP(j, K+1)
    			one[i].a[i][j] = 1;
    }

    REP(i, K+1) {
    	rotr[i].toE();
    	if (i == 1) {
    		rotr[i].toZero();
    		rotr[i].a[0][0] = 1;
    		rotr[i].a[1][K] = 1;
    		for (int j = 2; j <= K; j++)
    			rotr[i].a[j][j-1] = 1;
    	} else if (i > 1)
    		rotr[i] = rotr[1] * rotr[i-1];
    }

    REP(i, K+1) {
    	rotc[i].toE();
    	if (i == 1) {
    		rotc[i].toZero();
    		rotc[i].a[0][0] = 1;
    		rotc[i].a[K][1] = 1;
    		for (int j = 2; j <= K; j++)
    			rotc[i].a[j-1][j] = 1;
    	} else if (i > 1)
    		rotc[i] = rotc[i-1] * rotc[1];
    }


    two[1].toE();
    FOR(i, K)
    	two[1] = one[i] * two[1];

    int bit = 0;
    int num[70];
    while (n) {
    	num[bit++] = n % K;
    	n /= K;
    }

    for (int i = 2; i <= bit; i++) {
    	two[i].toE();
    	REP(j, K)
    		two[i] = rotr[j] * two[i-1] * rotc[j] * two[i];
    }

    reverse(num, num + bit);

    Matrix ret; ret.toE();

    int ps = 0;
    REP(i, bit) {
    	if (i == bit - 1)
    		REP(j, num[i])
    			ret = one[ps%K + 1] * ret, ps++;
    	else
    		REP(j, num[i])
    			ret = rotr[ps%K] * two[bit-i-1] * rotc[ps%K] * ret, ps++;
    }


    LL res = 1;
    FOR(i, K)
    	add(res, ret.a[i][0]);

    cout << res << endl;

    return 0;
}


int main() {
    return Main();
}

